/**
 * FocusMode Component - Hides all but selected node + dependencies
 */

import React, { useMemo } from 'react';
import { GraphData, Node } from '../types';

interface FocusModeProps {
  data: GraphData;
  selectedNodeId: string | null;
  onClearFocus: () => void;
  children: (filteredData: GraphData) => React.ReactNode;
}

/**
 * Focus Mode Component
 *
 * Filters graph data to show only the selected node and its direct dependencies.
 * All other nodes are hidden to reduce visual clutter and focus attention.
 */
const FocusMode: React.FC<FocusModeProps> = ({
  data,
  selectedNodeId,
  onClearFocus,
  children
}) => {
  /**
   * Calculate the set of visible nodes based on selected node
   * Includes: selected node + all direct neighbors (incoming + outgoing connections)
   */
  const filteredData = useMemo(() => {
    if (!selectedNodeId) {
      return data; // No focus, return all data
    }

    // Find all connected node IDs
    const connectedIds = new Set<string>([selectedNodeId]);

    // Add sources (nodes that point to selected)
    data.links.forEach((link) => {
      if (link.target === selectedNodeId) {
        connectedIds.add(link.source);
      }
      if (link.source === selectedNodeId) {
        connectedIds.add(link.target);
      }
    });

    // Filter nodes
    const filteredNodes = data.nodes.filter((node) =>
      connectedIds.has(node.id)
    );

    // Filter links (only those between visible nodes)
    const filteredLinks = data.links.filter((link) =>
      connectedIds.has(link.source) && connectedIds.has(link.target)
    );

    return {
      nodes: filteredNodes,
      links: filteredLinks
    };
  }, [data, selectedNodeId]);

  /**
   * Check if focus mode is active
   */
  const isFocused = selectedNodeId !== null;

  /**
   * Get the label of the focused node
   */
  const focusedNodeLabel = useMemo(() => {
    if (!selectedNodeId) return '';
    const node = data.nodes.find((n) => n.id === selectedNodeId);
    return node?.label || '';
  }, [data.nodes, selectedNodeId]);

  if (!isFocused) {
    return <>{children(data)}</>;
  }

  return (
    <div className="relative w-full h-full">
      {/* Focus Mode Banner */}
      <div className="absolute top-4 left-1/2 -translate-x-1/2 z-20 flex items-center gap-3 bg-cyan-600/90 backdrop-blur border border-cyan-400 rounded-lg px-4 py-2 shadow-lg">
        <span className="text-sm font-semibold text-white">
          Focus: {focusedNodeLabel}
        </span>
        <span className="text-xs text-cyan-100">
          ({filteredData.nodes.length} nodes, {filteredData.links.length} links)
        </span>
        <button
          onClick={onClearFocus}
          className="ml-2 px-2 py-1 bg-white/20 hover:bg-white/30 text-white text-xs rounded transition-colors"
          title="Clear focus (Cmd+Shift+F)"
        >
          ✕ Clear
        </button>
      </div>

      {/* Render filtered graph */}
      <div className="w-full h-full">
        {children(filteredData)}
      </div>

      {/* Dimmed overlay hint */}
      {filteredData.nodes.length < data.nodes.length && (
        <div className="absolute bottom-4 right-4 z-20 text-xs text-slate-500">
          {data.nodes.length - filteredData.nodes.length} nodes hidden
        </div>
      )}
    </div>
  );
};

export default FocusMode;

/**
 * subagent.ts - Execution result types for subagent operations
 *
 * Defines the contract for code execution by subagents with:
 * - Real-time progress streaming
 * - Change tracking with diffs
 * - Error handling and rollback support
 */

/**
 * Execution status for a subagent task
 */
export type ExecutionStatus =
  | 'queued'           // Waiting in pool
  | 'initializing'     // Starting up
  | 'running'          // Actively executing
  | 'awaiting_approval' // Waiting for user confirmation
  | 'completed'        // Finished successfully
  | 'failed'           // Errored out
  | 'cancelled'        // User cancelled
  | 'rolled_back';     // Changes were undone

/**
 * Severity level for execution messages
 */
export type MessageSeverity = 'info' | 'warning' | 'error' | 'success';

/**
 * Single progress message from subagent
 */
export interface ProgressMessage {
  id: string;
  timestamp: number;
  severity: MessageSeverity;
  message: string;
  details?: string;
  code?: string; // Error code if applicable
}

/**
 * File change with diff information
 */
export interface FileChange {
  path: string;
  changeType: 'create' | 'update' | 'delete';
  oldContent?: string;
  newContent?: string;
  diff?: string; // Unified diff format
  changeId?: string; // ID from change journal for rollback
}

/**
 * Complete execution result from subagent
 */
export interface ExecutionResult {
  executionId: string;
  taskId: string;
  status: ExecutionStatus;
  progress: number; // 0-100
  messages: ProgressMessage[];
  changes: FileChange[];
  startedAt: number;
  completedAt?: number;
  error?: {
    message: string;
    code: string;
    stack?: string;
  };
  metadata: {
    filesModified: number;
    linesChanged: number;
    subagentVersion: string;
  };
}

/**
 * Request to execute a task
 */
export interface ExecutionRequest {
  taskId: string;
  taskTitle: string;
  taskDescription: string;
  files: string[];
  priority: 'low' | 'medium' | 'high' | 'critical';
  timeout?: number; // milliseconds
}

/**
 * Configuration for subagent pool
 */
export interface SubagentPoolConfig {
  maxConcurrent: number;
  defaultTimeout: number;
  retryAttempts: number;
  retryDelay: number;
}

/**
 * Event emitted during execution
 */
export interface ExecutionEvent {
  type: 'progress' | 'status_change' | 'file_change' | 'error' | 'complete';
  executionId: string;
  timestamp: number;
  data: unknown;
}

/**
 * Approval request for destructive operations
 */
export interface ApprovalRequest {
  executionId: string;
  operation: string;
  description: string;
  files: string[];
  risks: string[];
  preview?: string; // Diff preview or code snippet
}

/**
 * Approval response
 */
export interface ApprovalResponse {
  approved: boolean;
  executionId: string;
  cancelExecution?: boolean;
}

/**
 * Rollback request
 */
export interface RollbackRequest {
  executionId: string;
  changeIds: string[];
  reason?: string;
}

/**
 * Rollback result
 */
export interface RollbackResult {
  success: boolean;
  filesRestored: string[];
  errors: string[];
  timestamp: number;
}

/**
 * Statistics for the execution pool
 */
export interface PoolStatistics {
  totalExecutions: number;
  activeExecutions: number;
  queuedExecutions: number;
  completedExecutions: number;
  failedExecutions: number;
  averageExecutionTime: number;
}

/**
 * Search Indexer - Builds searchable index from graph data
 */

import { GraphData, Node } from '../types';

/**
 * Search result item
 */
export interface SearchResultItem {
  id: string;
  type: 'node' | 'link';
  label: string;
  description?: string;
  nodeId: string;
  score: number;
  matchedFields: string[];
}

/**
 * Search index structure
 */
interface SearchIndex {
  nodes: Map<string, NodeIndexEntry>;
  links: Map<string, LinkIndexEntry>;
  labels: string[];
  allText: string[];
}

interface NodeIndexEntry {
  node: Node;
  labelLower: string;
  type: string;
  allText: string;
}

interface LinkIndexEntry {
  source: string;
  target: string;
  label?: string;
  labelLower?: string;
}

/**
 * SearchIndexer class
 *
 * Builds and maintains a searchable index over graph data
 * for instant search results with highlighting
 */
export class SearchIndexer {
  private index: SearchIndex;

  constructor() {
    this.index = {
      nodes: new Map(),
      links: new Map(),
      labels: [],
      allText: []
    };
  }

  /**
   * Build search index from graph data
   */
  buildIndex(data: GraphData): void {
    // Clear existing index
    this.index = {
      nodes: new Map(),
      links: new Map(),
      labels: [],
      allText: []
    };

    // Index nodes
    data.nodes.forEach((node) => {
      const labelLower = node.label.toLowerCase();
      const allText = `${node.label} ${node.type}`.toLowerCase();

      const entry: NodeIndexEntry = {
        node,
        labelLower,
        type: node.type,
        allText
      };

      this.index.nodes.set(node.id, entry);
      this.index.labels.push(node.label);
      this.index.allText.push(allText);
    });

    // Index links
    data.links.forEach((link, idx) => {
      const entry: LinkIndexEntry = {
        source: link.source,
        target: link.target,
        label: link.label,
        labelLower: link.label?.toLowerCase()
      };
      this.index.links.set(`link-${idx}`, entry);

      if (link.label) {
        this.index.labels.push(link.label);
        this.index.allText.push(link.label.toLowerCase());
      }
    });
  }

  /**
   * Search for nodes/links matching query
   * Returns sorted results by relevance score
   */
  search(query: string): SearchResultItem[] {
    if (!query.trim()) {
      return [];
    }

    const queryLower = query.toLowerCase();
    const results: SearchResultItem[] = [];

    // Search nodes
    this.index.nodes.forEach((entry, nodeId) => {
      const score = this.calculateScore(entry, queryLower);
      if (score > 0) {
        const matchedFields = this.getMatchedFields(entry, queryLower);
        results.push({
          id: nodeId,
          type: 'node',
          label: entry.node.label,
          description: `Type: ${entry.node.type}`,
          nodeId,
          score,
          matchedFields
        });
      }
    });

    // Search links (by label)
    this.index.links.forEach((entry, linkId) => {
      if (entry.labelLower) {
        const score = this.calculateLinkScore(entry, queryLower);
        if (score > 0) {
          const sourceNode = this.index.nodes.get(entry.source);
          const targetNode = this.index.nodes.get(entry.target);
          results.push({
            id: linkId,
            type: 'link',
            label: entry.label || '',
            description: `${sourceNode?.node.label || entry.source} → ${targetNode?.node.label || entry.target}`,
            nodeId: entry.source, // For navigation, go to source
            score,
            matchedFields: entry.labelLower.includes(queryLower) ? ['label'] : []
          });
        }
      }
    });

    // Sort by score (descending)
    return results.sort((a, b) => b.score - a.score);
  }

  /**
   * Get node by ID
   */
  getNode(nodeId: string): Node | undefined {
    return this.index.nodes.get(nodeId)?.node;
  }

  /**
   * Get all labels for autocomplete
   */
  getAllLabels(): string[] {
    return this.index.labels;
  }

  /**
   * Calculate relevance score for a node
   * Higher score = better match
   */
  private calculateScore(entry: NodeIndexEntry, query: string): number {
    let score = 0;

    // Exact label match = highest score
    if (entry.labelLower === query) {
      score += 100;
    }
    // Label starts with query = high score
    else if (entry.labelLower.startsWith(query)) {
      score += 50;
    }
    // Label contains query = medium score
    else if (entry.labelLower.includes(query)) {
      score += 25;
    }

    // Type match = bonus
    if (entry.type.toLowerCase().includes(query)) {
      score += 10;
    }

    // Word boundary matches = small bonus
    const words = query.split(/\s+/);
    words.forEach((word) => {
      if (entry.labelLower.includes(word)) {
        score += 5;
      }
    });

    return score;
  }

  /**
   * Calculate relevance score for a link
   */
  private calculateLinkScore(entry: LinkIndexEntry, query: string): number {
    if (!entry.labelLower) return 0;

    if (entry.labelLower === query) return 80;
    if (entry.labelLower.startsWith(query)) return 40;
    if (entry.labelLower.includes(query)) return 20;

    return 0;
  }

  /**
   * Get list of matched fields for highlighting
   */
  private getMatchedFields(entry: NodeIndexEntry, query: string): string[] {
    const matched: string[] = [];

    if (entry.labelLower.includes(query)) {
      matched.push('label');
    }
    if (entry.type.toLowerCase().includes(query)) {
      matched.push('type');
    }

    return matched;
  }
}

/**
 * Singleton instance for global use
 */
let globalIndexer: SearchIndexer | null = null;

export function getSearchIndexer(): SearchIndexer {
  if (!globalIndexer) {
    globalIndexer = new SearchIndexer();
  }
  return globalIndexer;
}

export function resetSearchIndexer(): void {
  globalIndexer = new SearchIndexer();
}

/**
 * subagentOrchestrator.ts - Pool management for code execution subagents
 *
 * Features:
 * - Max 3 concurrent executions
 * - Timeout handling with configurable limits
 * - Progress streaming via callbacks
 * - Queue management with priority
 * - Error handling and retry logic
 */

import { randomUUID } from 'crypto';
import type {
  ExecutionRequest,
  ExecutionResult,
  ExecutionStatus,
  ProgressMessage,
  FileChange,
  SubagentPoolConfig,
  PoolStatistics,
  ExecutionEvent,
} from '../types/subagent';

/**
 * Default configuration for subagent pool
 */
const DEFAULT_CONFIG: SubagentPoolConfig = {
  maxConcurrent: 3,
  defaultTimeout: 300000, // 5 minutes
  retryAttempts: 2,
  retryDelay: 1000, // 1 second
};

/**
 * Queue item for pending executions
 */
interface QueueItem {
  id: string;
  request: ExecutionRequest;
  priority: number;
  timestamp: number;
}

/**
 * Active execution with state
 */
interface ActiveExecution {
  id: string;
  request: ExecutionRequest;
  result: ExecutionResult;
  startTime: number;
  timeout: NodeJS.Timeout | null;
  abortController: AbortController;
}

/**
 * Callback for execution events
 */
type ExecutionCallback = (event: ExecutionEvent) => void;

/**
 * SubagentOrchestrator - Manages pool of subagent executions
 */
export class SubagentOrchestrator {
  private config: SubagentPoolConfig;
  private queue: Map<string, QueueItem> = new Map();
  private active: Map<string, ActiveExecution> = new Map();
  private history: Map<string, ExecutionResult> = new Map();
  private callbacks: Set<ExecutionCallback> = new Set();
  private processingQueue: boolean = false;

  constructor(config?: Partial<SubagentPoolConfig>) {
    this.config = { ...DEFAULT_CONFIG, ...config };
  }

  /**
   * Register a callback for execution events
   */
  public onEvent(callback: ExecutionCallback): () => void {
    this.callbacks.add(callback);
    return () => this.callbacks.delete(callback);
  }

  /**
   * Emit an event to all registered callbacks
   */
  private emitEvent(event: ExecutionEvent): void {
    this.callbacks.forEach(callback => {
      try {
        callback(event);
      } catch (error) {
        console.error('Error in execution callback:', error);
      }
    });
  }

  /**
   * Submit a task for execution
   */
  public async submit(request: ExecutionRequest): Promise<string> {
    const executionId = randomUUID();

    // Create execution result
    const result: ExecutionResult = {
      executionId,
      taskId: request.taskId,
      status: 'queued',
      progress: 0,
      messages: [],
      changes: [],
      startedAt: Date.now(),
      metadata: {
        filesModified: 0,
        linesChanged: 0,
        subagentVersion: '1.0.0',
      },
    };

    // Add to queue
    const queueItem: QueueItem = {
      id: executionId,
      request,
      priority: this.getPriorityValue(request.priority),
      timestamp: Date.now(),
    };

    this.queue.set(executionId, queueItem);
    this.history.set(executionId, result);

    this.emitEvent({
      type: 'status_change',
      executionId,
      timestamp: Date.now(),
      data: { status: 'queued' },
    });

    // Try to process queue
    this.processQueue();

    return executionId;
  }

  /**
   * Cancel an execution
   */
  public cancel(executionId: string): boolean {
    // Check active executions
    const active = this.active.get(executionId);
    if (active) {
      active.abortController.abort();
      if (active.timeout) {
        clearTimeout(active.timeout);
      }

      this.updateStatus(executionId, 'cancelled');
      this.active.delete(executionId);
      this.processQueue();
      return true;
    }

    // Check queued executions
    const queued = this.queue.get(executionId);
    if (queued) {
      this.queue.delete(executionId);
      this.updateStatus(executionId, 'cancelled');
      return true;
    }

    return false;
  }

  /**
   * Get execution result by ID
   */
  public getExecution(executionId: string): ExecutionResult | undefined {
    return this.history.get(executionId);
  }

  /**
   * Get all active executions
   */
  public getActiveExecutions(): ExecutionResult[] {
    return Array.from(this.active.values()).map(a => a.result);
  }

  /**
   * Get all queued executions
   */
  public getQueuedExecutions(): ExecutionResult[] {
    return Array.from(this.queue.values()).map(q => this.history.get(q.id)!);
  }

  /**
   * Get pool statistics
   */
  public getStatistics(): PoolStatistics {
    const completed = Array.from(this.history.values()).filter(
      r => r.status === 'completed'
    );

    const totalExecutionTime = completed.reduce((sum, r) => {
      return sum + (r.completedAt! - r.startedAt);
    }, 0);

    return {
      totalExecutions: this.history.size,
      activeExecutions: this.active.size,
      queuedExecutions: this.queue.size,
      completedExecutions: completed.length,
      failedExecutions: Array.from(this.history.values()).filter(
        r => r.status === 'failed'
      ).length,
      averageExecutionTime: completed.length > 0
        ? totalExecutionTime / completed.length
        : 0,
    };
  }

  /**
   * Process the execution queue
   */
  private processQueue(): void {
    if (this.processingQueue) {
      return;
    }

    this.processingQueue = true;

    try {
      // Sort queue by priority (highest first) and timestamp
      const sorted = Array.from(this.queue.entries()).sort(([, a], [, b]) => {
        if (a.priority !== b.priority) {
          return b.priority - a.priority; // Higher priority first
        }
        return a.timestamp - b.timestamp; // Earlier timestamp first
      });

      // Start as many as we can
      for (const [executionId, queueItem] of sorted) {
        if (this.active.size >= this.config.maxConcurrent) {
          break;
        }

        this.queue.delete(executionId);
        this.startExecution(queueItem);
      }
    } finally {
      this.processingQueue = false;
    }
  }

  /**
   * Start an execution
   */
  private startExecution(queueItem: QueueItem): void {
    const { id, request } = queueItem;

    const abortController = new AbortController();
    const timeout = request.timeout || this.config.defaultTimeout;

    // Create active execution
    const active: ActiveExecution = {
      id,
      request,
      result: this.history.get(id)!,
      startTime: Date.now(),
      timeout: null,
      abortController,
    };

    this.active.set(id, active);
    this.updateStatus(id, 'initializing');

    // Set up timeout
    active.timeout = setTimeout(() => {
      if (this.active.has(id)) {
        abortController.abort();
        this.failExecution(id, 'Execution timeout exceeded');
      }
    }, timeout);

    // Start the actual execution (simulated for now)
    this.simulateExecution(active);
  }

  /**
   * Simulate execution (replace with actual subagent call)
   * TODO: Integrate with actual AI service for code execution
   */
  private async simulateExecution(active: ActiveExecution): Promise<void> {
    const { id, request, result } = active;

    try {
      this.updateStatus(id, 'running');

      // Simulate progress updates
      const steps = [
        { progress: 10, message: 'Analyzing task requirements...' },
        { progress: 25, message: 'Reading source files...' },
        { progress: 40, message: 'Generating code changes...' },
        { progress: 60, message: 'Validating changes...' },
        { progress: 80, message: 'Applying changes...' },
        { progress: 95, message: 'Verifying results...' },
        { progress: 100, message: 'Complete!' },
      ];

      for (const step of steps) {
        await this.delay(500);
        this.addMessage(id, {
          id: randomUUID(),
          timestamp: Date.now(),
          severity: 'info',
          message: step.message,
        });
        this.updateProgress(id, step.progress);
      }

      // Simulate file changes
      if (request.files.length > 0) {
        const change: FileChange = {
          path: request.files[0],
          changeType: 'update',
          oldContent: '// Old content\n',
          newContent: '// New content\n',
          diff: '@@ -1,1 +1,1 @@\n-// Old content\n+// New content\n',
          changeId: randomUUID(),
        };
        this.addChange(id, change);
      }

      this.completeExecution(id);
    } catch (error) {
      this.failExecution(id, error instanceof Error ? error.message : 'Unknown error');
    }
  }

  /**
   * Complete an execution successfully
   */
  private completeExecution(executionId: string): void {
    const active = this.active.get(executionId);
    if (!active) return;

    if (active.timeout) {
      clearTimeout(active.timeout);
    }

    active.result.status = 'completed';
    active.result.progress = 100;
    active.result.completedAt = Date.now();

    this.active.delete(executionId);

    this.emitEvent({
      type: 'complete',
      executionId,
      timestamp: Date.now(),
      data: active.result,
    });

    this.processQueue();
  }

  /**
   * Fail an execution
   */
  private failExecution(executionId: string, errorMessage: string): void {
    const active = this.active.get(executionId);
    if (!active) return;

    if (active.timeout) {
      clearTimeout(active.timeout);
    }

    active.result.status = 'failed';
    active.result.error = {
      message: errorMessage,
      code: 'EXECUTION_FAILED',
    };
    active.result.completedAt = Date.now();

    this.addMessage(executionId, {
      id: randomUUID(),
      timestamp: Date.now(),
      severity: 'error',
      message: errorMessage,
    });

    this.active.delete(executionId);

    this.emitEvent({
      type: 'error',
      executionId,
      timestamp: Date.now(),
      data: { error: errorMessage },
    });

    this.processQueue();
  }

  /**
   * Update execution status
   */
  private updateStatus(executionId: string, status: ExecutionStatus): void {
    const result = this.history.get(executionId);
    if (result) {
      result.status = status;
      this.emitEvent({
        type: 'status_change',
        executionId,
        timestamp: Date.now(),
        data: { status },
      });
    }
  }

  /**
   * Update execution progress
   */
  private updateProgress(executionId: string, progress: number): void {
    const result = this.history.get(executionId);
    if (result) {
      result.progress = Math.min(100, Math.max(0, progress));
      this.emitEvent({
        type: 'progress',
        executionId,
        timestamp: Date.now(),
        data: { progress },
      });
    }
  }

  /**
   * Add a message to execution
   */
  private addMessage(executionId: string, message: ProgressMessage): void {
    const result = this.history.get(executionId);
    if (result) {
      result.messages.push(message);
      this.emitEvent({
        type: 'progress',
        executionId,
        timestamp: Date.now(),
        data: { message },
      });
    }
  }

  /**
   * Add a file change to execution
   */
  private addChange(executionId: string, change: FileChange): void {
    const result = this.history.get(executionId);
    if (result) {
      result.changes.push(change);
      result.metadata.filesModified++;

      if (change.diff) {
        const linesChanged = change.diff.split('\n').filter(
          line => line.startsWith('+') || line.startsWith('-')
        ).length;
        result.metadata.linesChanged += linesChanged;
      }

      this.emitEvent({
        type: 'file_change',
        executionId,
        timestamp: Date.now(),
        data: { change },
      });
    }
  }

  /**
   * Get numeric priority value
   */
  private getPriorityValue(priority: string): number {
    const values: Record<string, number> = {
      critical: 4,
      high: 3,
      medium: 2,
      low: 1,
    };
    return values[priority] || 0;
  }

  /**
   * Delay helper
   */
  private delay(ms: number): Promise<void> {
    return new Promise(resolve => setTimeout(resolve, ms));
  }

  /**
   * Clear all history
   */
  public clearHistory(): void {
    this.history.clear();
  }

  /**
   * Shutdown orchestrator
   */
  public shutdown(): void {
    // Cancel all active executions
    for (const [id, active] of this.active.entries()) {
      active.abortController.abort();
      if (active.timeout) {
        clearTimeout(active.timeout);
      }
      this.updateStatus(id, 'cancelled');
    }

    this.active.clear();
    this.queue.clear();
    this.callbacks.clear();
  }
}

// Singleton instance
let orchestratorInstance: SubagentOrchestrator | null = null;

/**
 * Get or create the singleton orchestrator instance
 */
export function getOrchestrator(config?: Partial<SubagentPoolConfig>): SubagentOrchestrator {
  if (!orchestratorInstance) {
    orchestratorInstance = new SubagentOrchestrator(config);
  }
  return orchestratorInstance;
}

/**
 * SearchModal - Global search UI with cmd+K trigger
 */

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { SearchResultItem } from '../utils/searchIndexer';

interface SearchModalProps {
  isOpen: boolean;
  onClose: () => void;
  results: SearchResultItem[];
  query: string;
  onQueryChange: (query: string) => void;
  onSelectResult: (item: SearchResultItem) => void;
}

/**
 * SearchModal Component
 *
 * Global search interface with keyboard navigation
 * Triggered via Cmd+K, provides instant search results
 */
const SearchModal: React.FC<SearchModalProps> = ({
  isOpen,
  onClose,
  results,
  query,
  onQueryChange,
  onSelectResult
}) => {
  const [selectedIndex, setSelectedIndex] = useState(0);
  const inputRef = useRef<HTMLInputElement>(null);
  const listRef = useRef<HTMLDivElement>(null);

  // Reset selection when results change
  useEffect(() => {
    setSelectedIndex(0);
  }, [results]);

  // Focus input when opened
  useEffect(() => {
    if (isOpen && inputRef.current) {
      inputRef.current.focus();
    }
  }, [isOpen]);

  // Keyboard navigation
  const handleKeyDown = useCallback((e: React.KeyboardEvent) => {
    switch (e.key) {
      case 'ArrowDown':
        e.preventDefault();
        setSelectedIndex((prev) =>
          prev < results.length - 1 ? prev + 1 : prev
        );
        break;
      case 'ArrowUp':
        e.preventDefault();
        setSelectedIndex((prev) => (prev > 0 ? prev - 1 : 0));
        break;
      case 'Enter':
        e.preventDefault();
        if (results[selectedIndex]) {
          onSelectResult(results[selectedIndex]);
        }
        break;
      case 'Escape':
        e.preventDefault();
        onClose();
        break;
    }
  }, [results, selectedIndex, onSelectResult, onClose]);

  // Scroll selected item into view
  useEffect(() => {
    if (listRef.current) {
      const selectedElement = listRef.current.children[selectedIndex] as HTMLElement;
      if (selectedElement) {
        selectedElement.scrollIntoView({
          block: 'nearest',
          behavior: 'smooth'
        });
      }
    }
  }, [selectedIndex]);

  if (!isOpen) return null;

  /**
   * Highlight matching text in result
   */
  const highlightMatch = (text: string, query: string) => {
    if (!query) return text;

    const regex = new RegExp(`(${query})`, 'gi');
    const parts = text.split(regex);

    return parts.map((part, idx) =>
      regex.test(part) ? (
        <mark key={idx} className="bg-cyan-500/30 text-cyan-300 rounded px-0.5">
          {part}
        </mark>
      ) : (
        part
      )
    );
  };

  /**
   * Get icon for result type
   */
  const getTypeIcon = (item: SearchResultItem) => {
    if (item.type === 'link') {
      return <span className="text-slate-400">↗️</span>;
    }
    // Node type icons based on description
    if (item.description?.includes('entry')) return <span className="text-cyan-400">🚪</span>;
    if (item.description?.includes('logic')) return <span className="text-violet-400">⚙️</span>;
    if (item.description?.includes('storage')) return <span className="text-amber-400">💾</span>;
    if (item.description?.includes('exit')) return <span className="text-red-400">🚪</span>;
    return <span className="text-slate-400">⬡</span>;
  };

  return (
    <div className="fixed inset-0 z-50 flex items-start justify-center pt-[20vh]">
      {/* Backdrop */}
      <div
        className="absolute inset-0 bg-black/60 backdrop-blur-sm"
        onClick={onClose}
      />

      {/* Modal */}
      <div
        className="relative w-full max-w-2xl mx-4 bg-slate-900 rounded-xl shadow-2xl border border-slate-700 overflow-hidden"
        onKeyDown={handleKeyDown}
      >
        {/* Header with search input */}
        <div className="flex items-center gap-3 px-4 py-3 border-b border-slate-700">
          <span className="text-slate-400">🔍</span>
          <input
            ref={inputRef}
            type="text"
            value={query}
            onChange={(e) => onQueryChange(e.target.value)}
            placeholder="Search nodes, links, functions..."
            className="flex-1 bg-transparent text-slate-200 placeholder-slate-500 focus:outline-none"
          />
          {query && (
            <button
              onClick={() => onQueryChange('')}
              className="p-1 hover:bg-slate-800 rounded transition-colors"
              title="Clear search"
            >
              ✕
            </button>
          )}
          <kbd className="px-2 py-1 bg-slate-800 text-slate-400 text-xs rounded">
            ESC
          </kbd>
        </div>

        {/* Results list */}
        <div
          ref={listRef}
          className="max-h-80 overflow-y-auto"
        >
          {results.length === 0 ? (
            <div className="py-8 text-center text-slate-500">
              {query ? (
                <>
                  <p className="text-lg mb-2">No results found</p>
                  <p className="text-sm">Try different keywords</p>
                </>
              ) : (
                <>
                  <p className="text-lg mb-2">Start typing to search</p>
                  <p className="text-sm">Search nodes, links, and functions</p>
                </>
              )}
            </div>
          ) : (
            <div className="py-2">
              {results.map((item, idx) => (
                <button
                  key={item.id}
                  onClick={() => onSelectResult(item)}
                  className={`w-full px-4 py-3 flex items-start gap-3 transition-colors ${
                    idx === selectedIndex
                      ? 'bg-cyan-500/10 border-l-2 border-cyan-500'
                      : 'hover:bg-slate-800 border-l-2 border-transparent'
                  }`}
                >
                  {/* Icon */}
                  <div className="mt-0.5">
                    {getTypeIcon(item)}
                  </div>

                  {/* Content */}
                  <div className="flex-1 text-left">
                    <div className="flex items-center gap-2">
                      <span className="text-slate-200 font-medium">
                        {highlightMatch(item.label, query)}
                      </span>
                      <span className={`text-xs px-1.5 py-0.5 rounded ${
                        item.type === 'node'
                          ? 'bg-violet-500/20 text-violet-400'
                          : 'bg-slate-700 text-slate-400'
                      }`}>
                        {item.type}
                      </span>
                    </div>
                    {item.description && (
                      <div className="text-sm text-slate-500 mt-0.5">
                        {highlightMatch(item.description, query)}
                      </div>
                    )}
                  </div>

                  {/* Score indicator */}
                  <div className="text-xs text-slate-600">
                    {item.score > 50 && '⭐'}
                  </div>
                </button>
              ))}
            </div>
          )}
        </div>

        {/* Footer with hints */}
        <div className="px-4 py-2 bg-slate-800/50 border-t border-slate-700 flex items-center justify-between text-xs text-slate-500">
          <div className="flex items-center gap-4">
            <span>
              <kbd className="px-1.5 py-0.5 bg-slate-700 rounded">↑↓</kbd> Navigate
            </span>
            <span>
              <kbd className="px-1.5 py-0.5 bg-slate-700 rounded">Enter</kbd> Select
            </span>
            <span>
              <kbd className="px-1.5 py-0.5 bg-slate-700 rounded">ESC</kbd> Close
            </span>
          </div>
          {results.length > 0 && (
            <span>{results.length} result{results.length !== 1 ? 's' : ''}</span>
          )}
        </div>
      </div>
    </div>
  );
};

export default SearchModal;

/**
 * useKeyboardShortcuts Hook - Global keyboard shortcut handling
 */

import { useEffect, useRef } from 'react';

export interface KeyboardShortcutConfig {
  key: string;
  ctrlKey?: boolean;
  metaKey?: boolean;
  shiftKey?: boolean;
  altKey?: boolean;
  handler: () => void;
  description?: string;
}

/**
 * useKeyboardShortcuts Hook
 *
 * Registers global keyboard shortcuts with proper modifier key handling
 * Supports Cmd (Mac) and Ctrl (Windows/Linux)
 */
export function useKeyboardShortcuts(
  shortcuts: KeyboardShortcutConfig[],
  enabled: boolean = true
) {
  const handlersRef = useRef<Map<string, () => void>>(new Map());

  useEffect(() => {
    if (!enabled) return;

    // Build handler map
    const handlerMap = new Map<string, () => void>();

    shortcuts.forEach((shortcut) => {
      const key = buildShortcutKey(shortcut);
      handlerMap.set(key, shortcut.handler);
    });

    handlersRef.current = handlerMap;

    // Keyboard event listener
    const handleKeyDown = (event: KeyboardEvent) => {
      // Ignore if in input/textarea
      const target = event.target as HTMLElement;
      if (
        target.tagName === 'INPUT' ||
        target.tagName === 'TEXTAREA' ||
        target.isContentEditable
      ) {
        // Allow Cmd+K even in inputs
        if (!(event.metaKey || event.ctrlKey) || event.key !== 'k') {
          return;
        }
      }

      const key = buildShortcutKeyFromEvent(event);
      const handler = handlersRef.current.get(key);

      if (handler) {
        event.preventDefault();
        event.stopPropagation();
        handler();
      }
    };

    window.addEventListener('keydown', handleKeyDown);

    return () => {
      window.removeEventListener('keydown', handleKeyDown);
    };
  }, [shortcuts, enabled]);
}

/**
 * Build a unique key for the shortcut configuration
 */
function buildShortcutKey(shortcut: KeyboardShortcutConfig): string {
  const parts: string[] = [];

  if (shortcut.ctrlKey) parts.push('ctrl');
  if (shortcut.metaKey) parts.push('meta');
  if (shortcut.shiftKey) parts.push('shift');
  if (shortcut.altKey) parts.push('alt');

  parts.push(shortcut.key.toLowerCase());

  return parts.join('+');
}

/**
 * Build a unique key from a keyboard event
 */
function buildShortcutKeyFromEvent(event: KeyboardEvent): string {
  const parts: string[] = [];

  if (event.ctrlKey) parts.push('ctrl');
  if (event.metaKey) parts.push('meta');
  if (event.shiftKey) parts.push('shift');
  if (event.altKey) parts.push('alt');

  parts.push(event.key.toLowerCase());

  return parts.join('+');
}

/**
 * Format a shortcut for display in UI
 */
export function formatShortcut(shortcut: KeyboardShortcutConfig): string {
  const parts: string[] = [];

  if (shortcut.ctrlKey) parts.push('Ctrl');
  if (shortcut.metaKey) parts.push('Cmd');
  if (shortcut.shiftKey) parts.push('Shift');
  if (shortcut.altKey) parts.push('Alt');

  parts.push(shortcut.key.charAt(0).toUpperCase() + shortcut.key.slice(1));

  // Detect platform and use appropriate modifier
  const isMac = navigator.platform.toUpperCase().indexOf('MAC') >= 0;
  return parts.join(isMac ? '' : '+').replace('CtrlCmd', isMac ? 'Cmd' : 'Ctrl');
}

/**
 * Default shortcuts for the app
 */
export function getDefaultShortcuts(handlers: {
  onOpenQuickActions: () => void;
  onFocusNode: () => void;
  onClearFocus: () => void;
  onCloseModals: () => void;
}): KeyboardShortcutConfig[] {
  return [
    {
      key: 'k',
      metaKey: true,
      handler: handlers.onOpenQuickActions,
      description: 'Open quick actions'
    },
    {
      key: 'f',
      metaKey: true,
      handler: handlers.onFocusNode,
      description: 'Focus selected node'
    },
    {
      key: 'f',
      metaKey: true,
      shiftKey: true,
      handler: handlers.onClearFocus,
      description: 'Clear focus'
    },
    {
      key: 'Escape',
      handler: handlers.onCloseModals,
      description: 'Close modals'
    }
  ];
}

/**
 * CodeExecutionPanel.tsx - Execution UI with progress tracking
 *
 * Features:
 * - Real-time progress display
 * - Streaming messages from subagent
 * - File change tracking with diff previews
 * - Execution controls (cancel, retry)
 * - Status indicators
 */

import React, { useState, useEffect, useCallback } from 'react';
import type { ExecutionResult, ProgressMessage, FileChange } from '../types/subagent';
import { getOrchestrator } from '../services/subagentOrchestrator';

export interface CodeExecutionPanelProps {
  taskId: string;
  taskTitle: string;
  onClose?: () => void;
}

interface FileChangeWithExpanded extends FileChange {
  expanded?: boolean;
}

const CodeExecutionPanel: React.FC<CodeExecutionPanelProps> = ({
  taskId,
  taskTitle,
  onClose,
}) => {
  const [execution, setExecution] = useState<ExecutionResult | null>(null);
  const [changes, setChanges] = useState<FileChangeWithExpanded[]>([]);
  const [isExecuting, setIsExecuting] = useState(false);

  // Subscribe to execution events
  useEffect(() => {
    const orchestrator = getOrchestrator();

    const unsubscribe = orchestrator.onEvent((event) => {
      if (event.executionId === execution?.executionId) {
        const updated = orchestrator.getExecution(event.executionId);
        if (updated) {
          setExecution(updated);
          setChanges(updated.changes.map(c => ({ ...c, expanded: false })));

          if (updated.status === 'completed' || updated.status === 'failed') {
            setIsExecuting(false);
          }
        }
      }
    });

    return unsubscribe;
  }, [execution?.executionId]);

  // Start execution
  const startExecution = useCallback(async () => {
    const orchestrator = getOrchestrator();
    setIsExecuting(true);

    const executionId = await orchestrator.submit({
      taskId,
      taskTitle,
      taskDescription: '', // Will be populated from task
      files: [],
      priority: 'medium',
    });

    const result = orchestrator.getExecution(executionId);
    if (result) {
      setExecution(result);
    }
  }, [taskId, taskTitle]);

  // Cancel execution
  const cancelExecution = useCallback(() => {
    if (execution) {
      const orchestrator = getOrchestrator();
      orchestrator.cancel(execution.executionId);
      setIsExecuting(false);
    }
  }, [execution]);

  // Toggle change expansion
  const toggleChange = useCallback((index: number) => {
    setChanges(prev =>
      prev.map((change, i) =>
        i === index ? { ...change, expanded: !change.expanded } : change
      )
    );
  }, []);

  // Get status color
  const getStatusColor = (status: string) => {
    const colors: Record<string, string> = {
      queued: 'bg-slate-700 text-slate-300',
      initializing: 'bg-blue-900/30 text-blue-400',
      running: 'bg-yellow-900/30 text-yellow-400',
      awaiting_approval: 'bg-purple-900/30 text-purple-400',
      completed: 'bg-green-900/30 text-green-400',
      failed: 'bg-red-900/30 text-red-400',
      cancelled: 'bg-slate-800 text-slate-400',
      rolled_back: 'bg-orange-900/30 text-orange-400',
    };
    return colors[status] || colors.queued;
  };

  // Get severity icon
  const getSeverityIcon = (severity: string) => {
    const icons: Record<string, string> = {
      info: 'ℹ️',
      warning: '⚠️',
      error: '❌',
      success: '✅',
    };
    return icons[severity] || icons.info;
  };

  return (
    <div className="bg-slate-900 border border-slate-700 rounded-lg overflow-hidden">
      {/* Header */}
      <div className="bg-slate-800 px-4 py-3 border-b border-slate-700">
        <div className="flex items-center justify-between">
          <div>
            <h3 className="text-white font-semibold">{taskTitle}</h3>
            {execution && (
              <div className="flex items-center gap-2 mt-1">
                <span className={`text-xs px-2 py-0.5 rounded ${getStatusColor(execution.status)}`}>
                  {execution.status.replace(/_/g, ' ').toUpperCase()}
                </span>
                <span className="text-xs text-slate-400">
                  {execution.progress}% complete
                </span>
              </div>
            )}
          </div>
          <div className="flex items-center gap-2">
            {!execution && (
              <button
                onClick={startExecution}
                disabled={isExecuting}
                className="px-3 py-1.5 text-sm bg-green-600 hover:bg-green-500 disabled:bg-slate-700 disabled:text-slate-500 text-white rounded transition-colors"
              >
                Execute
              </button>
            )}
            {execution && (execution.status === 'running' || execution.status === 'initializing') && (
              <button
                onClick={cancelExecution}
                className="px-3 py-1.5 text-sm bg-red-600 hover:bg-red-500 text-white rounded transition-colors"
              >
                Cancel
              </button>
            )}
            {onClose && (
              <button
                onClick={onClose}
                className="p-1.5 text-slate-400 hover:text-white hover:bg-slate-700 rounded transition-colors"
              >
                ✕
              </button>
            )}
          </div>
        </div>

        {/* Progress Bar */}
        {execution && execution.status !== 'queued' && (
          <div className="mt-3">
            <div className="w-full bg-slate-700 rounded-full h-2 overflow-hidden">
              <div
                className="bg-gradient-to-r from-blue-500 to-purple-500 h-full transition-all duration-300"
                style={{ width: `${execution.progress}%` }}
              />
            </div>
          </div>
        )}
      </div>

      {/* Content */}
      <div className="p-4 space-y-4 max-h-96 overflow-y-auto">
        {/* Messages */}
        {execution && execution.messages.length > 0 && (
          <div>
            <h4 className="text-sm font-semibold text-slate-300 mb-2">Progress</h4>
            <div className="space-y-1">
              {execution.messages.map((msg, idx) => (
                <div
                  key={idx}
                  className={`text-xs p-2 rounded ${
                    msg.severity === 'error'
                      ? 'bg-red-900/20 text-red-400'
                      : msg.severity === 'warning'
                      ? 'bg-yellow-900/20 text-yellow-400'
                      : msg.severity === 'success'
                      ? 'bg-green-900/20 text-green-400'
                      : 'bg-slate-800 text-slate-300'
                  }`}
                >
                  <span className="mr-1">{getSeverityIcon(msg.severity)}</span>
                  {msg.message}
                </div>
              ))}
            </div>
          </div>
        )}

        {/* File Changes */}
        {changes.length > 0 && (
          <div>
            <h4 className="text-sm font-semibold text-slate-300 mb-2">
              File Changes ({changes.length})
            </h4>
            <div className="space-y-2">
              {changes.map((change, idx) => (
                <div
                  key={idx}
                  className="bg-slate-800 border border-slate-700 rounded overflow-hidden"
                >
                  <button
                    onClick={() => toggleChange(idx)}
                    className="w-full px-3 py-2 flex items-center justify-between hover:bg-slate-700 transition-colors"
                  >
                    <div className="flex items-center gap-2">
                      <span className={change.expanded ? 'rotate-90' : ''}>▶</span>
                      <span className="text-sm font-mono text-cyan-400">{change.path}</span>
                      <span className={`text-xs px-1.5 py-0.5 rounded ${
                        change.changeType === 'create'
                          ? 'bg-green-900/30 text-green-400'
                          : change.changeType === 'delete'
                          ? 'bg-red-900/30 text-red-400'
                          : 'bg-blue-900/30 text-blue-400'
                      }`}>
                        {change.changeType}
                      </span>
                    </div>
                    {change.changeId && (
                      <span className="text-xs text-slate-500 font-mono">
                        {change.changeId.slice(0, 8)}
                      </span>
                    )}
                  </button>
                  {change.expanded && change.diff && (
                    <div className="px-3 py-2 border-t border-slate-700 bg-slate-900">
                      <pre className="text-xs font-mono text-slate-300 overflow-x-auto">
                        {change.diff}
                      </pre>
                    </div>
                  )}
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Error */}
        {execution?.error && (
          <div className="bg-red-900/20 border border-red-900/50 rounded p-3">
            <h4 className="text-sm font-semibold text-red-400 mb-1">Error</h4>
            <p className="text-xs text-red-300">{execution.error.message}</p>
            {execution.error.stack && (
              <details className="mt-2">
                <summary className="text-xs text-red-400 cursor-pointer hover:text-red-300">
                  Stack trace
                </summary>
                <pre className="text-xs text-red-300 mt-2 overflow-x-auto">
                  {execution.error.stack}
                </pre>
              </details>
            )}
          </div>
        )}

        {/* Metadata */}
        {execution && execution.status === 'completed' && (
          <div className="bg-slate-800 border border-slate-700 rounded p-3">
            <h4 className="text-sm font-semibold text-slate-300 mb-2">Summary</h4>
            <div className="grid grid-cols-2 gap-2 text-xs">
              <div className="text-slate-400">Files modified:</div>
              <div className="text-slate-200">{execution.metadata.filesModified}</div>
              <div className="text-slate-400">Lines changed:</div>
              <div className="text-slate-200">{execution.metadata.linesChanged}</div>
              <div className="text-slate-400">Duration:</div>
              <div className="text-slate-200">
                {execution.completedAt && execution.startedAt
                  ? `${((execution.completedAt - execution.startedAt) / 1000).toFixed(2)}s`
                  : 'N/A'}
              </div>
            </div>
          </div>
        )}

        {/* Empty state */}
        {!execution && !isExecuting && (
          <div className="text-center py-8">
            <p className="text-slate-400 text-sm">Ready to execute this task</p>
            <p className="text-slate-500 text-xs mt-1">
              Click "Execute" to start the code generation
            </p>
          </div>
        )}
      </div>
    </div>
  );
};

export default CodeExecutionPanel;

