      action: () => {
        onAutoLayout?.();
        onClose();
      },
      category: 'View'
    },
    {
      id: 'toggle-minimap',
      label: 'Toggle Mini Map',
      icon: '🗺️',
      description: 'Show/hide the mini map',
      action: () => {
        onToggleMiniMap?.();
        onClose();
      },
      category: 'View'
    },
    {
      id: 'export',
      label: 'Export Graph',
      icon: '📤',
      description: 'Export graph as image or JSON',
      action: () => {
        onExport?.();
        onClose();
      },
      category: 'File'
    }
  ];

  // Reset mode and selection when opened
  useEffect(() => {
    if (isOpen) {
      setMode('actions');
      setSelectedIndex(0);
      onSearchQueryChange?.('');
      inputRef.current?.focus();
    }
  }, [isOpen, onSearchQueryChange]);

  // Update mode based on query
  useEffect(() => {
    if (searchQuery.trim()) {
      setMode('search');
    } else {
      setMode('actions');
    }
  }, [searchQuery]);

  // Reset selection when results change
  useEffect(() => {
    setSelectedIndex(0);
  }, [searchResults, mode]);

  // Keyboard navigation
  const handleKeyDown = useCallback((e: React.KeyboardEvent) => {
    const items = mode === 'search' ? searchResults : quickActions;

    switch (e.key) {
      case 'ArrowDown':
        e.preventDefault();
        setSelectedIndex((prev) =>
          prev < items.length - 1 ? prev + 1 : prev
        );
        break;
      case 'ArrowUp':
        e.preventDefault();
        setSelectedIndex((prev) => (prev > 0 ? prev - 1 : 0));
        break;
      case 'Enter':
        e.preventDefault();
        if (mode === 'search' && searchResults[selectedIndex]) {
          onSearchResultSelect?.(searchResults[selectedIndex]);
        } else if (mode === 'actions' && quickActions[selectedIndex]) {
          quickActions[selectedIndex].action();
        }
        onClose();
        break;
      case 'Escape':
        e.preventDefault();
        onClose();
        break;
    }
  }, [mode, searchResults, selectedIndex, quickActions, onSearchResultSelect, onClose]);

  // Scroll selected item into view
  useEffect(() => {
    if (listRef.current) {
      const selectedElement = listRef.current.children[selectedIndex] as HTMLElement;
      if (selectedElement) {
        selectedElement.scrollIntoView({
          block: 'nearest',
          behavior: 'smooth'
        });
      }
    }
  }, [selectedIndex]);

  if (!isOpen) return null;

  const items = mode === 'search' ? searchResults : quickActions;
  const hasResults = items.length > 0;

  /**
   * Highlight matching text
   */
  const highlightMatch = (text: string, query: string) => {
    if (!query) return text;

    const regex = new RegExp(`(${query})`, 'gi');
    const parts = text.split(regex);

    return parts.map((part, idx) =>
      regex.test(part) ? (
        <mark key={idx} className="bg-cyan-500/30 text-cyan-300 rounded px-0.5">
          {part}
        </mark>
      ) : (
        part
      )
    );
  };

  return (
    <div className="fixed inset-0 z-50 flex items-start justify-center pt-[20vh]">
      {/* Backdrop */}
      <div
        className="absolute inset-0 bg-black/60 backdrop-blur-sm"
        onClick={onClose}
      />

      {/* Modal */}
      <div
        className="relative w-full max-w-2xl mx-4 bg-slate-900 rounded-xl shadow-2xl border border-slate-700 overflow-hidden"
        onKeyDown={handleKeyDown}
      >
        {/* Header with search input */}
        <div className="flex items-center gap-3 px-4 py-3 border-b border-slate-700">
          <span className="text-slate-400">
            {mode === 'search' ? '🔍' : '⚡'}
          </span>
          <input
            ref={inputRef}
            type="text"
            value={searchQuery}
            onChange={(e) => onSearchQueryChange?.(e.target.value)}
            placeholder={
              mode === 'search'
                ? 'Search nodes, links...'
                : 'What do you want to do?'
            }
            className="flex-1 bg-transparent text-slate-200 placeholder-slate-500 focus:outline-none"
          />
          {searchQuery && (
            <button
              onClick={() => onSearchQueryChange?.('')}
              className="p-1 hover:bg-slate-800 rounded transition-colors"
              title="Clear search"
            >
              ✕
            </button>
          )}
          <kbd className="px-2 py-1 bg-slate-800 text-slate-400 text-xs rounded">
            ESC
          </kbd>
        </div>

        {/* Content */}
        <div
          ref={listRef}
          className="max-h-80 overflow-y-auto"
        >
          {!hasResults ? (
            <div className="py-8 text-center text-slate-500">
              {mode === 'search' ? (
                <>
                  <p className="text-lg mb-2">No results found</p>
                  <p className="text-sm">Try different keywords</p>
                </>
              ) : null}
            </div>
          ) : (
            <div className="py-2">
              {/* Show category header for actions */}
              {mode === 'actions' && (
                <div className="px-4 py-1 text-xs text-slate-500 font-semibold uppercase">
                  Quick Actions
                </div>
              )}

              {mode === 'actions' &&
                quickActions.map((action, idx) => (
                  <button
                    key={action.id}
                    onClick={() => {
                      action.action();
                      onClose();
                    }}
                    className={`w-full px-4 py-3 flex items-start gap-3 transition-colors ${
                      idx === selectedIndex
                        ? 'bg-cyan-500/10 border-l-2 border-cyan-500'
                        : 'hover:bg-slate-800 border-l-2 border-transparent'
                    }`}
                  >
                    <div className="mt-0.5 text-xl">{action.icon}</div>
                    <div className="flex-1 text-left">
                      <div className="text-slate-200 font-medium">
                        {action.label}
                      </div>
                      {action.description && (
                        <div className="text-sm text-slate-500 mt-0.5">
                          {action.description}
                        </div>
                      )}
                    </div>
                    {action.category && (
                      <span className="text-xs text-slate-600">{action.category}</span>
                    )}
                  </button>
                ))}

              {mode === 'search' &&
                searchResults.map((item, idx) => (
                  <button
                    key={item.id}
                    onClick={() => {
                      onSearchResultSelect?.(item);
                      onClose();
                    }}
                    className={`w-full px-4 py-3 flex items-start gap-3 transition-colors ${
                      idx === selectedIndex
                        ? 'bg-cyan-500/10 border-l-2 border-cyan-500'
                        : 'hover:bg-slate-800 border-l-2 border-transparent'
                    }`}
                  >
                    <div className="mt-0.5">
                      {item.type === 'link' ? (
                        <span className="text-slate-400">↗️</span>
                      ) : (
                        <span className="text-cyan-400">⬡</span>
                      )}
                    </div>
                    <div className="flex-1 text-left">
                      <div className="flex items-center gap-2">
                        <span className="text-slate-200 font-medium">
                          {highlightMatch(item.label, searchQuery)}
                        </span>
                        <span
                          className={`text-xs px-1.5 py-0.5 rounded ${
                            item.type === 'node'
                              ? 'bg-violet-500/20 text-violet-400'
                              : 'bg-slate-700 text-slate-400'
                          }`}
                        >
                          {item.type}
                        </span>
                      </div>
                      {item.description && (
                        <div className="text-sm text-slate-500 mt-0.5">
                          {highlightMatch(item.description, searchQuery)}
                        </div>
                      )}
                    </div>
                  </button>
                ))}
            </div>
          )}
        </div>

        {/* Footer */}
        <div className="px-4 py-2 bg-slate-800/50 border-t border-slate-700 flex items-center justify-between text-xs text-slate-500">
          <div className="flex items-center gap-4">
            <span>
              <kbd className="px-1.5 py-0.5 bg-slate-700 rounded">↑↓</kbd> Navigate
            </span>
            <span>
              <kbd className="px-1.5 py-0.5 bg-slate-700 rounded">Enter</kbd> Select
            </span>
            <span>
              <kbd className="px-1.5 py-0.5 bg-slate-700 rounded">ESC</kbd> Close
            </span>
          </div>
          {hasResults && (
            <span>{items.length} result{items.length !== 1 ? 's' : ''}</span>
          )}
        </div>
      </div>
    </div>
  );
};

export default QuickActionsMenu;

/**
 * LiveDiffViewer.tsx - Real-time diff visualization
 *
 * Features:
 * - Show diffs as changes happen
 * - Syntax highlighting for code
 * - Side-by-side or unified view
 * - Change statistics
 */

import React, { useState, useEffect } from 'react';
import type { FileChange } from '../types/subagent';

export interface LiveDiffViewerProps {
  changes: FileChange[];
  autoScroll?: boolean;
  maxHeight?: string;
}

type ViewMode = 'unified' | 'side-by-side';

const LiveDiffViewer: React.FC<LiveDiffViewerProps> = ({
  changes,
  autoScroll = true,
  maxHeight = '500px',
}) => {
  const [viewMode, setViewMode] = useState<ViewMode>('unified');
  const [selectedChange, setSelectedChange] = useState<number | null>(null);

  // Auto-select latest change
  useEffect(() => {
    if (autoScroll && changes.length > 0 && selectedChange === null) {
      setSelectedChange(changes.length - 1);
    }
  }, [changes.length, autoScroll, selectedChange]);

  // Calculate statistics
  const stats = changes.reduce((acc, change) => {
    if (change.diff) {
      const additions = (change.diff.match(/\n\+/g) || []).length;
      const deletions = (change.diff.match(/\n-/g) || []).length;
      return {
        additions: acc.additions + additions,
        deletions: acc.deletions + deletions,
        files: acc.files + 1,
      };
    }
    return acc;
  }, { additions: 0, deletions: 0, files: 0 });

  // Get change type color
  const getChangeTypeColor = (type: string) => {
    const colors: Record<string, string> = {
      create: 'text-green-400 bg-green-900/30',
      update: 'text-blue-400 bg-blue-900/30',
      delete: 'text-red-400 bg-red-900/30',
    };
    return colors[type] || colors.update;
  };

  // Render unified diff
  const renderUnifiedDiff = (change: FileChange) => {
    if (!change.diff) {
      return (
        <div className="text-slate-400 text-sm p-4">
          No diff available for this change
        </div>
      );
    }

    const lines = change.diff.split('\n');
    return (
      <div className="font-mono text-xs">
        {lines.map((line, idx) => {
          const lineClass = line.startsWith('+')
            ? 'bg-green-900/20 text-green-300'
            : line.startsWith('-')
            ? 'bg-red-900/20 text-red-300'
            : line.startsWith('@@')
            ? 'bg-purple-900/30 text-purple-300 font-bold'
            : 'text-slate-300';

          return (
            <div key={idx} className={`px-2 ${lineClass}`}>
              {line || ' '}
            </div>
          );
        })}
      </div>
    );
  };

  // Render side-by-side diff
  const renderSideBySideDiff = (change: FileChange) => {
    if (!change.oldContent || !change.newContent) {
      return renderUnifiedDiff(change);
    }

    const oldLines = change.oldContent.split('\n');
    const newLines = change.newContent.split('\n');
    const maxLines = Math.max(oldLines.length, newLines.length);

    return (
      <div className="font-mono text-xs grid grid-cols-2 gap-1">
        <div className="bg-red-900/10">
          <div className="bg-red-900/30 text-red-300 px-2 py-1 font-bold sticky top-0">
            REMOVED
          </div>
          {oldLines.map((line, idx) => (
            <div key={idx} className="px-2 text-slate-300 border-b border-slate-700/50">
              {line || ' '}
            </div>
          ))}
        </div>
        <div className="bg-green-900/10">
          <div className="bg-green-900/30 text-green-300 px-2 py-1 font-bold sticky top-0">
            ADDED
          </div>
          {newLines.map((line, idx) => (
            <div key={idx} className="px-2 text-slate-300 border-b border-slate-700/50">
              {line || ' '}
            </div>
          ))}
        </div>
      </div>
    );
  };

  const selectedChangeData = selectedChange !== null ? changes[selectedChange] : null;

  return (
    <div className="bg-slate-900 border border-slate-700 rounded-lg overflow-hidden">
      {/* Header */}
      <div className="bg-slate-800 px-4 py-3 border-b border-slate-700">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-4">
            <h3 className="text-white font-semibold">Live Diff Viewer</h3>
            <div className="flex items-center gap-2 text-xs">
              <span className="text-slate-400">{stats.files} files</span>
              <span className="text-green-400">+{stats.additions}</span>
              <span className="text-red-400">-{stats.deletions}</span>
            </div>
          </div>
          <div className="flex items-center gap-2">
            <button
              onClick={() => setViewMode('unified')}
              className={`px-2 py-1 text-xs rounded transition-colors ${
                viewMode === 'unified'
                  ? 'bg-blue-600 text-white'
                  : 'bg-slate-700 text-slate-300 hover:bg-slate-600'
              }`}
            >
              Unified
            </button>
            <button
              onClick={() => setViewMode('side-by-side')}
              className={`px-2 py-1 text-xs rounded transition-colors ${
                viewMode === 'side-by-side'
                  ? 'bg-blue-600 text-white'
                  : 'bg-slate-700 text-slate-300 hover:bg-slate-600'
              }`}
            >
              Side by Side
            </button>
          </div>
        </div>
      </div>

      <div className="flex" style={{ maxHeight }}>
        {/* File list */}
        <div className="w-64 border-r border-slate-700 overflow-y-auto">
          <div className="p-2 space-y-1">
            {changes.map((change, idx) => (
              <button
                key={idx}
                onClick={() => setSelectedChange(idx)}
                className={`w-full text-left p-2 rounded transition-colors ${
                  selectedChange === idx
                    ? 'bg-blue-900/30 border border-blue-700'
                    : 'hover:bg-slate-800 border border-transparent'
                }`}
              >
                <div className="flex items-center justify-between gap-1">
                  <span className="text-xs font-mono text-cyan-400 truncate flex-1">
                    {change.path.split('/').pop()}
                  </span>
                  <span className={`text-xs px-1 py-0.5 rounded ${getChangeTypeColor(change.changeType)}`}>
                    {change.changeType === 'create' ? '+' : change.changeType === 'delete' ? '-' : '±'}
                  </span>
                </div>
                <div className="text-xs text-slate-500 truncate mt-0.5">
                  {change.path}
                </div>
              </button>
            ))}
          </div>
        </div>

        {/* Diff content */}
        <div className="flex-1 overflow-y-auto">
          {selectedChangeData ? (
            <div>
              {/* File header */}
              <div className="bg-slate-800 px-4 py-2 border-b border-slate-700">
                <div className="flex items-center justify-between">
                  <div>
                    <div className="text-sm font-mono text-cyan-400">
                      {selectedChangeData.path}
                    </div>
                    <div className="text-xs text-slate-400 mt-0.5">
                      {selectedChangeData.changeType === 'create'
                        ? 'New file created'
                        : selectedChangeData.changeType === 'delete'
                        ? 'File deleted'
                        : 'File modified'}
                    </div>
                  </div>
                  {selectedChangeData.changeId && (
                    <div className="text-xs text-slate-500">
                      Change ID: {selectedChangeData.changeId.slice(0, 8)}
                    </div>
                  )}
                </div>
              </div>

              {/* Diff content */}
              <div className="overflow-x-auto">
                {viewMode === 'unified'
                  ? renderUnifiedDiff(selectedChangeData)
                  : renderSideBySideDiff(selectedChangeData)}
              </div>
            </div>
          ) : (
            <div className="flex items-center justify-center h-full text-slate-400">
              <div className="text-center">
                <p className="text-sm">No changes to display</p>
                <p className="text-xs mt-1">
                  {changes.length === 0
                    ? 'Execute a task to see changes'
                    : 'Select a file from the list to view its diff'}
                </p>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default LiveDiffViewer;

/**
 * ContextMenu - Right-click context menus for common operations
 */

import React, { useEffect, useRef, useState } from 'react';

export interface ContextMenuItem {
  id: string;
  label: string;
  icon?: string;
  action: () => void;
  disabled?: boolean;
  shortcut?: string;
  separator?: boolean;
}

interface ContextMenuProps {
  x: number;
  y: number;
  items: ContextMenuItem[];
  onClose: () => void;
}

/**
 * ContextMenu Component
 *
 * Right-click context menu for quick access to common operations
 * Auto-positions to avoid screen edges
 */
const ContextMenu: React.FC<ContextMenuProps> = ({ x, y, items, onClose }) => {
  const menuRef = useRef<HTMLDivElement>(null);
  const [position, setPosition] = useState({ x, y });

  // Adjust position to avoid screen edges
  useEffect(() => {
    if (!menuRef.current) return;

    const menu = menuRef.current;
    const rect = menu.getBoundingClientRect();
    const viewportWidth = window.innerWidth;
    const viewportHeight = window.innerHeight;

    let adjustedX = x;
    let adjustedY = y;

    // Check right edge
    if (x + rect.width > viewportWidth - 10) {
      adjustedX = x - rect.width;
    }

    // Check bottom edge
    if (y + rect.height > viewportHeight - 10) {
      adjustedY = y - rect.height;
    }

    // Ensure minimum margins
    adjustedX = Math.max(10, adjustedX);
    adjustedY = Math.max(10, adjustedY);

    setPosition({ x: adjustedX, y: adjustedY });
  }, [x, y]);

  // Close on click outside
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
        onClose();
      }
    };

    const handleEscape = (event: KeyboardEvent) => {
      if (event.key === 'Escape') {
        onClose();
      }
    };

    document.addEventListener('mousedown', handleClickOutside);
    document.addEventListener('keydown', handleEscape);

    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
      document.removeEventListener('keydown', handleEscape);
    };
  }, [onClose]);

  // Handle item click
  const handleItemClick = (item: ContextMenuItem) => {
    if (!item.disabled) {
      item.action();
      onClose();
    }
  };

  return (
    <div
      ref={menuRef}
      className="fixed z-50 min-w-48 bg-slate-900 rounded-lg shadow-2xl border border-slate-700 py-1"
      style={{
        left: position.x,
        top: position.y
      }}
    >
      {items.map((item, idx) => {
        if (item.separator) {
          return (
            <div
              key={`sep-${idx}`}
              className="my-1 border-t border-slate-700"
            />
          );
        }

        return (
          <button
            key={item.id}
            onClick={() => handleItemClick(item)}
            disabled={item.disabled}
            className={`w-full px-3 py-2 flex items-center justify-between gap-3 text-left transition-colors ${
              item.disabled
                ? 'opacity-50 cursor-not-allowed'
                : 'hover:bg-slate-800 text-slate-200'
            }`}
          >
            <div className="flex items-center gap-2">
              {item.icon && <span className="text-sm">{item.icon}</span>}
              <span className="text-sm">{item.label}</span>
            </div>
            {item.shortcut && (
              <kbd className="text-xs text-slate-500 bg-slate-800 px-1.5 py-0.5 rounded">
                {item.shortcut}
              </kbd>
            )}
          </button>
        );
      })}
    </div>
  );
};

/**
 * Hook to manage context menu state
 */
export function useContextMenu() {
  const [contextMenu, setContextMenu] = useState<{
    x: number;
    y: number;
    items: ContextMenuItem[];
  } | null>(null);

  const showContextMenu = (x: number, y: number, items: ContextMenuItem[]) => {
    setContextMenu({ x, y, items });
  };

  const hideContextMenu = () => {
    setContextMenu(null);
  };

  const ContextMenuWrapper = () => {
    if (!contextMenu) return null;

    return (
      <ContextMenu
        x={contextMenu.x}
        y={contextMenu.y}
        items={contextMenu.items}
        onClose={hideContextMenu}
      />
    );
  };

  return {
    showContextMenu,
    hideContextMenu,
    ContextMenu: ContextMenuWrapper
  };
}

