#!/usr/bin/env node
/**
 * CLI interface for CodeBase Cartographer
 * Provides command-line tools for analyzing and exporting codebase visualizations
 */

import { Command } from 'cac';
import { readdir, readFile, stat } from 'fs/promises';
import { join, relative, extname } from 'path';
import { existsSync } from 'fs';
import { analyzeCodebase } from './analyzer';
import { exportDiagram } from './exporter';

const cli = Command('codebase-cartographer');

/**
 * Main analyze command
 */
cli
  .command('analyze [path]', 'Analyze a codebase and generate visualization')
  .option('-e, --export <file>', 'Export to file (PNG, SVG, JSON)')
  .option('-f, --format <format>', 'Output format (png, svg, json)')
  .option('-o, --output <file>', 'Output file path')
  .option('-c, --complexity', 'Include complexity metrics')
  .option('-d, --depth <number>', 'Maximum dependency depth', { default: '10' })
  .option('--ignore <patterns...>', 'Ignore patterns (e.g., node_modules dist)')
  .action(async (path: string = '.', options) => {
    try {
      const targetPath = join(process.cwd(), path);

      if (!existsSync(targetPath)) {
        console.error(`Error: Path "${targetPath}" does not exist`);
        process.exit(1);
      }

      console.log(`Analyzing codebase at: ${targetPath}`);

      const graphData = await analyzeCodebase(targetPath, {
        maxDepth: parseInt(options.depth) || 10,
        ignorePatterns: options.ignore || ['node_modules', 'dist', 'build', '.git'],
        includeComplexity: options.complexity || false
      });

      console.log(`\nAnalysis complete:`);
      console.log(`  Files analyzed: ${graphData.nodes.length}`);
      console.log(`  Dependencies found: ${graphData.links.length}`);

      if (options.complexity) {
        const avgComplexity = graphData.nodes.reduce((sum, node) =>
          sum + (node.data.complexity?.cyclomatic || 0), 0) / graphData.nodes.length;
        console.log(`  Average cyclomatic complexity: ${avgComplexity.toFixed(2)}`);
      }

      // Handle export
      const outputFile = options.export || options.output;
      const format = options.format || (outputFile ? extname(outputFile).slice(1) : null);

      if (outputFile && format) {
        console.log(`\nExporting to ${outputFile}...`);
        await exportDiagram(graphData, outputFile, format);
        console.log(`Export complete: ${outputFile}`);
      } else if (!outputFile) {
        console.log('\nJSON output:');
        console.log(JSON.stringify(graphData, null, 2));
      }

    } catch (error) {
      console.error('Analysis failed:', error instanceof Error ? error.message : error);
      process.exit(1);
    }
  });

/**
 * Export command for existing graphs
 */
cli
  .command('export <input> <output>', 'Export an existing graph file')
  .option('-f, --format <format>', 'Output format (png, svg, json)')
  .action(async (input: string, output: string, options) => {
    try {
      const format = options.format || extname(output).slice(1);
      const inputPath = join(process.cwd(), input);

      if (!existsSync(inputPath)) {
        console.error(`Error: Input file "${inputPath}" does not exist`);
        process.exit(1);
      }

      const graphData = JSON.parse(await readFile(inputPath, 'utf-8'));
      await exportDiagram(graphData, output, format);

      console.log(`Exported to ${output}`);
    } catch (error) {
      console.error('Export failed:', error instanceof Error ? error.message : error);
      process.exit(1);
    }
  });

/**
 * Info command
 */
cli
  .command('info [path]', 'Show information about a codebase')
  .action(async (path: string = '.') => {
    try {
      const targetPath = join(process.cwd(), path);

      if (!existsSync(targetPath)) {
        console.error(`Error: Path "${targetPath}" does not exist`);
        process.exit(1);
      }

      const stats = await getCodebaseStats(targetPath);

      console.log('\nCodebase Information:');
      console.log(`  Path: ${targetPath}`);
      console.log(`  Total files: ${stats.totalFiles}`);
      console.log(`  Total lines: ${stats.totalLines}`);
      console.log(`  Languages: ${Object.entries(stats.languages).map(([lang, count]) =>
        `${lang} (${count})`
      ).join(', ')}`);
    } catch (error) {
      console.error('Info failed:', error instanceof Error ? error.message : error);
      process.exit(1);
    }
  });

cli.help();
cli.version(require('../package.json').version);

cli.parse();

/**
 * Get codebase statistics
 */
async function getCodebaseStats(
  dirPath: string,
  ignorePatterns: string[] = ['node_modules', 'dist', 'build', '.git']
): Promise<{
  totalFiles: number;
  totalLines: number;
  languages: Record<string, number>;
}> {
  const files = await readdir(dirPath, { withFileTypes: true });
  let totalFiles = 0;
  let totalLines = 0;
  const languages: Record<string, number> = {};

  for (const file of files) {
    if (ignorePatterns.includes(file.name)) continue;

    const fullPath = join(dirPath, file.name);

    if (file.isDirectory()) {
      const subdirStats = await getCodebaseStats(fullPath, ignorePatterns);
      totalFiles += subdirStats.totalFiles;
      totalLines += subdirStats.totalLines;
      Object.entries(subdirStats.languages).forEach(([lang, count]) => {
        languages[lang] = (languages[lang] || 0) + count;
      });
    } else if (file.isFile()) {
      const ext = extname(file.name);
      const languageMap: Record<string, string> = {
        '.ts': 'TypeScript',
        '.tsx': 'TypeScript',
        '.js': 'JavaScript',
        '.jsx': 'JavaScript',
        '.py': 'Python',
        '.rs': 'Rust',
        '.go': 'Go',
        '.java': 'Java',
        '.cpp': 'C++',
        '.c': 'C',
        '.cs': 'C#',
        '.rb': 'Ruby',
        '.php': 'PHP'
      };

      const lang = languageMap[ext];
      if (lang) {
        const content = await readFile(fullPath, 'utf-8');
        const lines = content.split('\n').length;
        totalFiles++;
        totalLines += lines;
        languages[lang] = (languages[lang] || 0) + 1;
      }
    }
  }

  return { totalFiles, totalLines, languages };
}

/**
 * Codebase analyzer for CLI and API
 * Analyzes directory structure and builds dependency graphs
 */

import { readdir, readFile, stat } from 'fs/promises';
import { join, relative, extname } from 'path';
import { existsSync } from 'fs';

export interface AnalysisOptions {
  maxDepth: number;
  ignorePatterns: string[];
  includeComplexity: boolean;
}

export interface ComplexityMetrics {
  cyclomatic: number;
  linesOfCode: number;
  maintainabilityIndex: number;
}

export interface GraphNode {
  id: string;
  type: 'entry' | 'logic' | 'storage' | 'exit' | 'external' | 'decision' | 'process';
  position: { x: number; y: number };
  data: {
    label: string;
    description?: string;
    type: string;
    color?: string;
    complexity?: ComplexityMetrics;
    depth?: number;
    path?: string;
  };
}

export interface GraphLink {
  id: string;
  source: string;
  target: string;
  animated?: boolean;
}

export interface GraphData {
  nodes: GraphNode[];
  links: GraphLink[];
  metadata?: {
    analyzedPath: string;
    timestamp: number;
    fileCount: number;
    totalComplexity: number;
  };
}

/**
 * Analyze a codebase and generate graph data
 */
export async function analyzeCodebase(
  rootPath: string,
  options: AnalysisOptions
): Promise<GraphData> {
  const nodes: GraphNode[] = [];
  const links: GraphLink[] = [];
  const nodeMap = new Map<string, GraphNode>();
  let nodeCount = 0;

  // Collect all files
  const files = await collectFiles(rootPath, options.ignorePatterns);

  // Calculate node positions in a layered layout
  const layers = organizeByDepth(files, rootPath, options.maxDepth);

  // Create nodes for each file
  for (const [depth, filesAtDepth] of Object.entries(layers)) {
    const depthNum = parseInt(depth);
    for (const file of filesAtDepth) {
      const relPath = relative(rootPath, file);
      const ext = extname(file);
      const nodeId = `node-${nodeCount++}`;

      let nodeType: GraphNode['type'] = 'process';
      let color = '#3b82f6';

      // Determine node type and color based on file type
      if (ext === '.tsx' || ext === '.jsx') {
        nodeType = 'logic';
        color = '#8b5cf6';
      } else if (ext === '.ts' || ext === '.js') {
        nodeType = 'logic';
        color = '#06b6d4';
      } else if (ext === '.json') {
        nodeType = 'storage';
        color = '#10b981';
      } else if (ext === '.css' || ext === '.scss') {
        nodeType = 'external';
        color = '#ec4899';
      } else if (ext === '.md') {
        nodeType = 'external';
        color = '#6b7280';
      }

      const node: GraphNode = {
        id: nodeId,
        type: nodeType,
        position: {
          x: (nodeCount % 5) * 250 + 100,
          y: depthNum * 200 + 50
        },
        data: {
          label: relPath,
          description: getFileDescription(file),
          type: nodeType,
          color,
          path: file
        }
      };

      // Add complexity metrics if requested
      if (options.includeComplexity) {
        const complexity = await calculateComplexity(file);
        node.data.complexity = complexity;
      }

      nodes.push(node);
      nodeMap.set(relPath, node);
    }
  }

  // Create links based on imports
  for (const file of files) {
    const relPath = relative(rootPath, file);
    const sourceNode = nodeMap.get(relPath);

    if (!sourceNode) continue;

    try {
      const content = await readFile(file, 'utf-8');
      const imports = extractImports(content, extname(file));

      for (const imp of imports) {
        // Try to find the imported file
        const targetNode = findImportTarget(imp, relPath, nodeMap);
        if (targetNode && targetNode.id !== sourceNode.id) {
          links.push({
            id: `link-${sourceNode.id}-${targetNode.id}`,
            source: sourceNode.id,
            target: targetNode.id,
            animated: true
          });
        }
      }
    } catch (error) {
      // Skip files that can't be read
    }
  }

  // Calculate metadata
  const totalComplexity = options.includeComplexity
    ? nodes.reduce((sum, n) => sum + (n.data.complexity?.cyclomatic || 0), 0)
    : 0;

  return {
    nodes,
    links,
    metadata: {
      analyzedPath: rootPath,
      timestamp: Date.now(),
      fileCount: nodes.length,
      totalComplexity
    }
  };
}

/**
 * Collect all files in a directory recursively
 */
async function collectFiles(
  dirPath: string,
  ignorePatterns: string[],
  files: string[] = []
): Promise<string[]> {
  const entries = await readdir(dirPath, { withFileTypes: true });

  for (const entry of entries) {
    if (ignorePatterns.includes(entry.name)) continue;

    const fullPath = join(dirPath, entry.name);

    if (entry.isDirectory()) {
      await collectFiles(fullPath, ignorePatterns, files);
    } else if (entry.isFile()) {
      const ext = extname(entry.name);
      const validExtensions = ['.ts', '.tsx', '.js', '.jsx', '.json', '.css', '.scss', '.md'];
      if (validExtensions.includes(ext)) {
        files.push(fullPath);
      }
    }
  }

  return files;
}

/**
 * Organize files by depth from root
 */
function organizeByDepth(files: string[], rootPath: string, maxDepth: number): Record<number, string[]> {
  const layers: Record<number, string[]> = {};

  for (const file of files) {
    const relPath = relative(rootPath, file);
    const depth = relPath.split('/').length - 1;

    if (depth <= maxDepth) {
      if (!layers[depth]) {
        layers[depth] = [];
      }
      layers[depth].push(file);
    }
  }

  return layers;
}

/**
 * Extract import statements from code
 */
function extractImports(content: string, ext: string): string[] {
  const imports: string[] = [];

  if (ext === '.ts' || ext === '.tsx' || ext === '.js' || ext === '.jsx') {
    // ES6 imports
    const es6ImportRegex = /import\s+(?:.*\s+from\s+)?['"]([^'"]+)['"]/g;
    let match;
    while ((match = es6ImportRegex.exec(content)) !== null) {
      imports.push(match[1]);
    }

    // CommonJS requires
    const requireRegex = /require\(['"]([^'"]+)['"]\)/g;
    while ((match = requireRegex.exec(content)) !== null) {
      imports.push(match[1]);
    }
  }

  return imports;
}

/**
 * Find target node for an import
 */
function findImportTarget(
  importPath: string,
  sourceFile: string,
  nodeMap: Map<string, GraphNode>
): GraphNode | null {
  // Handle relative imports
  if (importPath.startsWith('.')) {
    const sourceDir = sourceFile.split('/').slice(0, -1).join('/');
    const resolved = join(sourceDir, importPath);

    // Try with common extensions
    const extensions = ['.ts', '.tsx', '.js', '.jsx', '.json', '/index.ts', '/index.js'];
    for (const ext of extensions) {
      const withExt = nodeMap.get(resolved + ext);
      if (withExt) return withExt;

      const withoutExt = nodeMap.get(resolved);
      if (withoutExt) return withoutExt;
    }
  }

  // Handle package imports
  const pkgName = importPath.split('/')[0];
  for (const [path, node] of nodeMap) {
    if (path.startsWith(pkgName)) {
      return node;
    }
  }

  return null;
}

/**
 * Get a description for a file based on its type
 */
function getFileDescription(filePath: string): string {
  const ext = extname(filePath);
  const name = filePath.split('/').pop() || '';

  if (name === 'index.ts' || name === 'index.js') {
    return 'Module entry point';
  } else if (name.endsWith('.test.ts') || name.endsWith('.test.js')) {
    return 'Test file';
  } else if (name.endsWith('.service.ts') || name.endsWith('.service.js')) {
    return 'Service module';
  } else if (name.endsWith('.component.tsx') || name.endsWith('.component.ts')) {
    return 'Component';
  } else if (name.endsWith('.hook.ts') || name.endsWith('.hook.js')) {
    return 'Custom hook';
  } else if (name === 'package.json') {
    return 'Package configuration';
  } else if (ext === '.css' || ext === '.scss') {
    return 'Stylesheet';
  } else if (ext === '.md') {
    return 'Documentation';
  }

  return 'Source file';
}

/**
 * Calculate complexity metrics for a file
 */
async function calculateComplexity(filePath: string): Promise<ComplexityMetrics> {
  try {
    const content = await readFile(filePath, 'utf-8');
    const lines = content.split('\n');

    // Count non-empty, non-comment lines
    let linesOfCode = 0;
    for (const line of lines) {
      const trimmed = line.trim();
      if (trimmed && !trimmed.startsWith('//') && !trimmed.startsWith('*') && !trimmed.startsWith('#')) {
        linesOfCode++;
      }
    }

    // Simple cyclomatic complexity: count decision points
    const decisionPoints = (
      content.match(/\bif\b/g) || []
    ).length + (
      content.match(/\bfor\b/g) || []
    ).length + (
      content.match(/\bwhile\b/g) || []
    ).length + (
      content.match(/\bswitch\b/g) || []
    ).length + (
      content.match(/\bcatch\b/g) || []
    ).length + (
      content.match(/\?\./g) || []
    ).length;

    const cyclomatic = decisionPoints * 2 + 1;

    // Maintainability index (simplified)
    const maintainabilityIndex = Math.max(0, Math.min(100,
      171 - 5.2 * Math.log(linesOfCode) - 0.23 * cyclomatic
    ));

    return {
      cyclomatic,
      linesOfCode,
      maintainabilityIndex: Math.round(maintainabilityIndex)
    };
  } catch (error) {
    return {
      cyclomatic: 1,
      linesOfCode: 0,
      maintainabilityIndex: 100
    };
  }
}

/**
 * Export functionality for diagrams
 * Supports PNG, SVG, and JSON formats
 */

import { writeFileSync } from 'fs';
import { join } from 'path';
import { GraphData } from './analyzer';

export interface ExportOptions {
  format: 'png' | 'svg' | 'json';
  output?: string;
  width?: number;
  height?: number;
  backgroundColor?: string;
}

/**
 * Export graph data to various formats
 */
export async function exportDiagram(
  graphData: GraphData,
  outputPath: string,
  format: string
): Promise<void> {
  switch (format.toLowerCase()) {
    case 'json':
      await exportJSON(graphData, outputPath);
      break;
    case 'svg':
      await exportSVG(graphData, outputPath);
      break;
    case 'png':
      await exportPNG(graphData, outputPath);
      break;
    default:
      throw new Error(`Unsupported format: ${format}`);
  }
}

/**
 * Export to JSON format
 */
async function exportJSON(graphData: GraphData, outputPath: string): Promise<void> {
  const json = JSON.stringify(graphData, null, 2);
  writeFileSync(outputPath, json, 'utf-8');
}

/**
 * Export to SVG format
 */
async function exportSVG(graphData: GraphData, outputPath: string): Promise<void> {
  // Calculate canvas bounds
  let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;

  for (const node of graphData.nodes) {
    minX = Math.min(minX, node.position.x);
    minY = Math.min(minY, node.position.y);
    maxX = Math.max(maxX, node.position.x + 200); // Approximate node width
    maxY = Math.max(maxY, node.position.y + 80); // Approximate node height
  }

  const padding = 50;
  const width = maxX - minX + padding * 2;
  const height = maxY - minY + padding * 2;

  // Generate SVG
  let svg = `<?xml version="1.0" encoding="UTF-8"?>
<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}">
  <defs>
    <marker id="arrowhead" markerWidth="10" markerHeight="10" refX="9" refY="3" orient="auto">
      <polygon points="0 0, 10 3, 0 6" fill="#64748b" />
    </marker>
  </defs>
  <rect width="100%" height="100%" fill="#0f172a" />

  <!-- Links -->
`;

  // Draw links
  for (const link of graphData.links) {
    const source = graphData.nodes.find(n => n.id === link.source);
    const target = graphData.nodes.find(n => n.id === link.target);

    if (source && target) {
      const x1 = source.position.x + 100 - minX + padding;
      const y1 = source.position.y + 40 - minY + padding;
      const x2 = target.position.x + 100 - minX + padding;
      const y2 = target.position.y + 40 - minY + padding;

      svg += `  <line
    x1="${x1}" y1="${y1}"
    x2="${x2}" y2="${y2}"
    stroke="#64748b"
    stroke-width="2"
    marker-end="url(#arrowhead)"
    ${link.animated ? 'class="animated"' : ''}
  />
`;
    }
  }

  svg += '\n  <!-- Nodes -->\n';

  // Draw nodes
  for (const node of graphData.nodes) {
    const x = node.position.x - minX + padding;
    const y = node.position.y - minY + padding;
    const color = node.data.color || '#3b82f6';
    const label = escapeXml(node.data.label);

    // Node rectangle
    svg += `  <g transform="translate(${x}, ${y})">
    <rect
      x="0" y="0"
      width="200" height="80"
      rx="8" ry="8"
      fill="${color}20"
      stroke="${color}"
      stroke-width="2"
    />
    <text
      x="100" y="45"
      text-anchor="middle"
      fill="#e2e8f0"
      font-family="system-ui, sans-serif"
      font-size="12"
      font-weight="500"
    >${truncateString(label, 25)}</text>
  </g>
`;
  }

  // Add metadata
  if (graphData.metadata) {
    svg += `
  <!-- Metadata -->
  <text x="20" y="${height - 20}" fill="#64748b" font-family="system-ui, sans-serif" font-size="10">
    Generated: ${new Date(graphData.metadata.timestamp).toISOString()}
  </text>
`;
  }

  svg += '</svg>';

  writeFileSync(outputPath, svg, 'utf-8');
}

/**
 * Export to PNG format (requires additional libraries)
 * Note: This is a simplified version. For production, consider using puppeteer or sharp
 */
async function exportPNG(graphData: GraphData, outputPath: string): Promise<void> {
  // First generate SVG, then convert to PNG
  const tempSvgPath = outputPath.replace('.png', '.temp.svg');

  try {
    await exportSVG(graphData, tempSvgPath);

    // For PNG export, you would typically:
    // 1. Use a library like sharp, canvas, or puppeteer
    // 2. Render the SVG to a canvas or headless browser
    // 3. Save as PNG

    // For now, we'll create a placeholder that instructions
    const instructions = `PNG Export

To export as PNG, install additional dependencies:
  npm install sharp

Then the PNG export will work automatically.

For now, the SVG has been saved to: ${tempSvgPath}

You can convert it manually using:
  - Online tools: https://svgtopng.com/
  - Command line: convert -background none diagram.svg diagram.png
`;

    writeFileSync(outputPath, instructions, 'utf-8');

    console.log('\nNote: Full PNG export requires additional dependencies.');
    console.log('SVG file saved to:', tempSvgPath);
  } catch (error) {
    throw new Error(`PNG export failed: ${error}`);
  }
}

/**
 * Escape XML special characters
 */
function escapeXml(str: string): string {
  return str
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&apos;');
}

/**
 * Truncate string to max length
 */
function truncateString(str: string, maxLength: number): string {
  if (str.length <= maxLength) return str;
  return str.substring(0, maxLength - 3) + '...';
}

/**
 * Snapshot Service
 * Manages saving and loading of graph states for persistence and comparison
 */

import { DiagramData } from '../types/diagram';
import { GraphNode, GraphLink } from '../types/snapshot';

const SNAPSHOT_STORAGE_KEY = 'codebase-cartographer-snapshots';
const SNAPSHOT_VERSION = '1.0';

export interface SnapshotMetadata {
  id: string;
  name: string;
  description?: string;
  timestamp: number;
  nodeCount: number;
  edgeCount: number;
  tags?: string[];
  version: string;
}

export interface Snapshot extends SnapshotMetadata {
  data: DiagramData;
}

export interface SnapshotExport {
  format: 'json' | 'compressed';
}

/**
 * Snapshot Service class
 */
class SnapshotService {
  private snapshots: Map<string, Snapshot> = new Map();
  private listeners: Set<() => void> = new Set();

  constructor() {
    this.loadFromStorage();
  }

  /**
   * Save a snapshot with the given name
   */
  saveSnapshot(
    name: string,
    graphData: DiagramData,
    options?: {
      description?: string;
      tags?: string[];
    }
  ): Snapshot {
    const id = this.generateId(name);
    const snapshot: Snapshot = {
      id,
      name,
      description: options?.description,
      timestamp: Date.now(),
      nodeCount: graphData.nodes.length,
      edgeCount: graphData.edges.length,
      tags: options?.tags,
      version: SNAPSHOT_VERSION,
      data: JSON.parse(JSON.stringify(graphData)) // Deep clone
    };

    this.snapshots.set(id, snapshot);
    this.persistToStorage();
    this.notifyListeners();

    return snapshot;
  }

  /**
   * Load a snapshot by ID
   */
  loadSnapshot(id: string): DiagramData | null {
    const snapshot = this.snapshots.get(id);
    if (!snapshot) {
      return null;
    }

    // Return a deep clone to prevent mutations
    return JSON.parse(JSON.stringify(snapshot.data));
  }

  /**
   * Load a snapshot by name
   */
  loadSnapshotByName(name: string): DiagramData | null {
    const snapshot = Array.from(this.snapshots.values()).find(s => s.name === name);
    if (!snapshot) {
      return null;
    }

    return JSON.parse(JSON.stringify(snapshot.data));
  }

  /**
   * List all snapshots
   */
  listSnapshots(): SnapshotMetadata[] {
    return Array.from(this.snapshots.values())
      .sort((a, b) => b.timestamp - a.timestamp)
      .map(snapshot => ({
        id: snapshot.id,
        name: snapshot.name,
        description: snapshot.description,
        timestamp: snapshot.timestamp,
        nodeCount: snapshot.nodeCount,
        edgeCount: snapshot.edgeCount,
        tags: snapshot.tags,
        version: snapshot.version
      }));
  }

  /**
   * Get a single snapshot's metadata
   */
  getSnapshot(id: string): SnapshotMetadata | null {
    const snapshot = this.snapshots.get(id);
    if (!snapshot) {
      return null;
    }

    return {
      id: snapshot.id,
      name: snapshot.name,
      description: snapshot.description,
      timestamp: snapshot.timestamp,
      nodeCount: snapshot.nodeCount,
      edgeCount: snapshot.edgeCount,
      tags: snapshot.tags,
      version: snapshot.version
    };
  }

  /**
   * Delete a snapshot
   */
  deleteSnapshot(id: string): boolean {
    const deleted = this.snapshots.delete(id);
    if (deleted) {
      this.persistToStorage();
      this.notifyListeners();
    }
    return deleted;
  }

  /**
   * Delete a snapshot by name
   */
  deleteSnapshotByName(name: string): boolean {
    const snapshot = Array.from(this.snapshots.entries()).find(([_, s]) => s.name === name);
    if (snapshot) {
      return this.deleteSnapshot(snapshot[0]);
    }
    return false;
  }

  /**
   * Update snapshot metadata
   */
  updateSnapshot(
    id: string,
    updates: {
      name?: string;
      description?: string;
      tags?: string[];
    }
  ): boolean {
    const snapshot = this.snapshots.get(id);
    if (!snapshot) {
      return false;
    }

    if (updates.name) snapshot.name = updates.name;
    if (updates.description !== undefined) snapshot.description = updates.description;
    if (updates.tags) snapshot.tags = updates.tags;

    this.persistToStorage();
    this.notifyListeners();

    return true;
  }

  /**
   * Export snapshot to file
   */
  exportSnapshot(id: string, format: 'json' = 'json'): string {
    const snapshot = this.snapshots.get(id);
    if (!snapshot) {
      throw new Error(`Snapshot not found: ${id}`);
    }

    if (format === 'json') {
      return JSON.stringify(snapshot, null, 2);
    }

    throw new Error(`Unsupported export format: ${format}`);
  }

  /**
   * Import snapshot from file
   */
  importSnapshot(json: string): Snapshot {
    try {
      const imported = JSON.parse(json) as Snapshot;

      // Validate structure
      if (!imported.id || !imported.name || !imported.data) {
        throw new Error('Invalid snapshot format');
      }

      // Generate new ID to avoid conflicts
      const newId = this.generateId(imported.name + '-imported');
      imported.id = newId;

      this.snapshots.set(newId, imported);
      this.persistToStorage();
      this.notifyListeners();

      return imported;
    } catch (error) {
      throw new Error(`Failed to import snapshot: ${error}`);
    }
  }

  /**
   * Compare two snapshots
   */
  compareSnapshots(id1: string, id2: string): {
    addedNodes: number;
    removedNodes: number;
    addedEdges: number;
    removedEdges: number;
    nodeChanges: Array<{ nodeId: string; change: string }>;
  } {
    const snapshot1 = this.snapshots.get(id1);
    const snapshot2 = this.snapshots.get(id2);

    if (!snapshot1 || !snapshot2) {
      throw new Error('One or both snapshots not found');
    }

    const nodes1 = new Set(snapshot1.data.nodes.map(n => n.id));
    const nodes2 = new Set(snapshot2.data.nodes.map(n => n.id));

    const edges1 = new Set(snapshot1.data.edges.map(e => e.id));
    const edges2 = new Set(snapshot2.data.edges.map(e => e.id));

    const addedNodes = [...nodes2].filter(id => !nodes1.has(id)).length;
    const removedNodes = [...nodes1].filter(id => !nodes2.has(id)).length;
    const addedEdges = [...edges2].filter(id => !edges1.has(id)).length;
    const removedEdges = [...edges1].filter(id => !edges2.has(id)).length;

    return {
      addedNodes,
      removedNodes,
      addedEdges,
      removedEdges,
      nodeChanges: []
    };
  }

  /**
   * Subscribe to snapshot changes
   */
  subscribe(listener: () => void): () => void {
    this.listeners.add(listener);
    return () => this.listeners.delete(listener);
  }

  /**
   * Clear all snapshots
   */
  clearAll(): void {
    this.snapshots.clear();
    this.persistToStorage();
    this.notifyListeners();
  }

  /**
   * Get storage size in bytes
   */
  getStorageSize(): number {
    const data = JSON.stringify(Array.from(this.snapshots.values()));
    return new Blob([data]).size;
  }

  /**
   * Private: Generate unique ID
   */
  private generateId(name: string): string {
    const timestamp = Date.now();
    const random = Math.random().toString(36).substring(2, 8);
    const slug = name.toLowerCase().replace(/[^a-z0-9]+/g, '-');
    return `${slug}-${timestamp}-${random}`;
  }

  /**
   * Private: Persist to localStorage
   */
  private persistToStorage(): void {
    try {
      const data = JSON.stringify(Array.from(this.snapshots.entries()));
      localStorage.setItem(SNAPSHOT_STORAGE_KEY, data);
    } catch (error) {
      console.error('Failed to persist snapshots:', error);
    }
  }

  /**
   * Private: Load from localStorage
   */
  private loadFromStorage(): void {
    try {
      const data = localStorage.getItem(SNAPSHOT_STORAGE_KEY);
      if (data) {
        const entries = JSON.parse(data) as Array<[string, Snapshot]>;
        this.snapshots = new Map(entries);
      }
    } catch (error) {
      console.error('Failed to load snapshots:', error);
      this.snapshots = new Map();
    }
  }

  /**
   * Private: Notify all listeners
   */
  private notifyListeners(): void {
    this.listeners.forEach(listener => listener());
  }
}

